import math

def max_search_depth(N: int) -> int:
    """Exact maximum depth for hypotenuse <= N. O(1) time. Certified by Theorem C."""
    if N < 5:
        return -1
    D = int((-3 + math.sqrt(2 * N + 1)) / 2)
    while 2*(D+1)**2 + 6*(D+1) + 5 <= N:
        D += 1
    while D >= 0 and 2*D**2 + 6*D + 5 > N:
        D -= 1
    return D

def min_hypotenuse_at_depth(d: int) -> int:
    """Exact minimum hypotenuse at depth d: 2d^2 + 6d + 5. Certified by Theorem A."""
    return 2*d*d + 6*d + 5

# Examples
for N in [100, 1000, 10000, 100000]:
    D = max_search_depth(N)
    print(f"N={N}: depth={D}, min_hyp={min_hypotenuse_at_depth(D)}")

import math

def child_a(t):
    a, b, c = t
    return (a - 2*b + 2*c, 2*a - b + 2*c, 2*a - 2*b + 3*c)

def child_b(t):
    a, b, c = t
    return (a + 2*b + 2*c, 2*a + b + 2*c, 2*a + 2*b + 3*c)

def child_c(t):
    a, b, c = t
    return (-a + 2*b + 2*c, -2*a + b + 2*c, -2*a + 2*b + 3*c)

def max_search_depth(N):
    if N < 5: return -1
    D = int((-3 + math.sqrt(2*N + 1)) / 2)
    while 2*(D+1)**2 + 6*(D+1) + 5 <= N: D += 1
    while D >= 0 and 2*D**2 + 6*D + 5 > N: D -= 1
    return D

def enumerate_triples(N):
    D = max_search_depth(N)
    if D < 0: return []
    result = []
    stack = [((3, 4, 5), 0)]
    while stack:
        triple, depth = stack.pop()
        if triple[2] <= N:
            result.append(triple)
        if depth < D:
            for gen in [child_a, child_b, child_c]:
                child = gen(triple)
                if child[2] <= N:
                    stack.append((child, depth + 1))
    return sorted(result, key=lambda t: (t[2], t[0]))

# Example
triples = enumerate_triples(100)
print(f"Primitive Pythagorean triples with c <= 100: {len(triples)}")
for t in triples:
    print(f"  {t}  check: {t[0]}^2 + {t[1]}^2 = {t[0]**2 + t[1]**2} = {t[2]}^2 = {t[2]**2}")

def extremal_triple(d):
    """The unique minimum-hypotenuse triple at depth d. O(1). Formally verified."""
    return (2*d + 3, 2*d**2 + 6*d + 4, 2*d**2 + 6*d + 5)

# Display the extremal geodesic
print("The Extremal Geodesic (All-A Branch):")
for d in range(15):
    a, b, c = extremal_triple(d)
    print(f"  Depth {d:>2}: ({a:>4}, {b:>6}, {c:>6})  ")
    assert a**2 + b**2 == c**2, "Pythagorean check failed!"
print("All triples verified as Pythagorean.")
